package patrol

import (
    "time"
)

type PatrolTask struct {
    ID          string
    RouteID     string
    RangerID    string
    StartTime   time.Time
    EndTime     time.Time
    Status      string
    Events      []PatrolEvent
}

type PatrolEvent struct {
    Type      string
    Latitude  float64
    Longitude float64
    Timestamp time.Time
    Photos    []string
    Notes     string
}

type PatrolScheduler struct {
    tasks  map[string]*PatrolTask
}

func (ps *PatrolScheduler) CreateTask(task *PatrolTask) error {
    ps.tasks[task.ID] = task
    return nil
}
